L["Second table to compare."] = "要比較的第二個表格。"
-- en: "Selected nonempty unit token, unchanged in native calls."
L["Selected nonempty unit token, unchanged in native calls."] = "所選的非空單位代碼，在原生呼叫中保持不變。"
-- en: "Selected nonempty unit token, unchanged in native/provider calls."
L["Selected nonempty unit token, unchanged in native/provider calls."] = "所選的非空單位代碼，在原生/提供者呼叫中保持不變。"
-- en: "Selected nonempty unit token."
L["Selected nonempty unit token."] = "所選的非空單位代碼。"
-- en: "Selected nonempty unit token; this call alone does not establish presence."
L["Selected nonempty unit token; this call alone does not establish presence."] = "所選的非空單位代碼；僅憑此呼叫不能確定其存在。"
-- en: "Selected nonempty unit token; unchanged native argument."
L["Selected nonempty unit token; unchanged native argument."] = "所選的非空單位代碼；作為原生參數保持不變。"
-- en: "Selected unit token forwarded as the only provider argument."
L["Selected unit token forwarded as the only provider argument."] = "作為唯一的提供者參數轉送的所選單位代碼。"
-- en: "Selected unit token, unchanged in observations."
L["Selected unit token, unchanged in observations."] = "所選的單位代碼，在觀測中保持不變。"
-- en: "Selector widget supporting SetList, SetValue, SetLabel, SetDisabled and callbacks."
L["Selector widget supporting SetList, SetValue, SetLabel, SetDisabled and callbacks."] = "支援 SetList、SetValue、SetLabel、SetDisabled 與回呼的選擇器元件。"
-- en: "Shared evaluation cache; nil observes directly without a per-pass cache."
L["Shared evaluation cache; nil observes directly without a per-pass cache."] = "共用的評估快取；為 nil 時直接觀測，不使用每輪次的快取。"
-- en: "Source array whose ipairs prefix is inserted without copying nested values."
L["Source array whose ipairs prefix is inserted without copying nested values."] = "來源陣列，其 ipairs 前綴會被插入，巢狀的值不會被複製。"
-- en: "Specialization scope used to resolve spell suggestions."
L["Specialization scope used to resolve spell suggestions."] = "用於解析法術建議的專精範圍。"
-- en: "Spell ID or client-recognized spell name whose charges should be read."
